      const inputs = row.querySelectorAll('.inline-input');
      if (inputs[0]) inputs[0].value = account.account_name || '';
      if (inputs[1]) inputs[1].value = account.username || '';
      if (inputs[2]) inputs[2].value = account.password || '';

      setDropdownValue(row, 0, account.role || '-');
      setDropdownValue(row, 1, account.dealer_level || '-');
      setDropdownValue(row, 2, account.discount_level || '-');
      setDropdownValue(row, 3, account.status || 'Active');

      const checkbox = row.querySelector('[data-row-select]');
